def url_unescape(data):
  return re.sub('%([0-9a-fA-F]{2})',
    lambda m: unichr(int(m.group(1), 16)), data)

def delete_attribute(self, key):
  if isinstance(key, int):
    del self.children[key:key+1]
  else:
    del self.attributes[key]

